head.script:

	scwin.onpageload = function() {
		scwin.unitTest();	
	};

	scwin.onpageunload = function() {

	};


scwin.chk_com1_oncheckboxclick = function(index,isChecked,value) {
	//chk_com1.setSelectedInfo([{index:0,checked:true}, {index:3,checked:true}]);

	if(index==2 && isChecked==true)
	{
		chk_com1.setSelectedInfo([{index:3,checked:false}]);
	}
	else if(index==3 && isChecked==true)
	{
		chk_com1.setSelectedInfo([{index:2,checked:false}]);
	}
};

	scwin.checkVal = function() {
		const txtVal = WebSquare.wUnit.getDomById('chk_com1_label').innerText;

		return txtVal.includes("라벨1") && txtVal.includes("라벨2");
	};

	scwin.unitTest = function() {
		//Unit 
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('chk_com1_label').click();");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('mf_chk_com1_itemTable_0_checkbox').click();");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('mf_chk_com1_itemTable_1_checkbox').click();");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('chk_com1_label').click();");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	};

	scwin.unitTest();
